```ts
/** Bytes of each stream kept for LLM consumption. The spec is explicit: not optional. */
export const LLM_OUTPUT_TAIL_BYTES = 2048;

/** Cap for readFile, which needs whole documents, not a tail. */
const MAX_READ_BYTES = 1024 * 1024;

type Keep = "head" | "tail";

class Capture {
  readonly stream: Writable;
  private chunks: Buffer[] = [];
  private kept = 0;
  total = 0;

  constructor(private readonly cap: number, private readonly keep: Keep) {
    this.stream = new Writable({
      write: (chunk: Buffer, _enc, cb) => {
        this.add(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
        cb();
      },
    });
  }

  private add(chunk: Buffer) {
    this.total += chunk.length;
    if (this.keep === "head") {
      if (this.kept >= this.cap) return;
      const room = this.cap - this.kept;
      const slice = chunk.length > room ? chunk.subarray(0, room) : chunk;
      this.chunks.push(slice);
      this.kept += slice.length;
      return;
    }
    this.chunks.push(chunk);
    this.kept += chunk.length;
    // Drop whole chunks from the front while the next chunk still covers the tail.
    while (this.chunks.length > 1 && this.kept - this.chunks[0]!.length >= this.cap) {
      this.kept -= this.chunks.shift()!.length;
    }
    if (this.kept > this.cap) {
      const head = this.chunks[0]!;
      const drop = this.kept - this.cap;
      this.chunks[0] = head.subarray(drop);
      this.kept -= drop;
    }
  }

  text(): string {
    const dropped = this.total - this.kept;
    const tail = Buffer.concat(this.chunks).toString("utf8");
    const clean = this.keep === "tail" ? tail.replace(/^\uFFFD+/, "") : tail;
    if (dropped === 0) return clean;
    return this.keep === "head"
      ? `${clean}\n…[truncated: kept first ${this.kept} of ${this.total} bytes]`
      : `…[truncated: kept last ${this.kept} of ${this.total} bytes]…\n${clean}`;
  }
}
```

