+/** Pull the image if it is not local yet. */
+async function ensureImage(image: string): Promise<void> {
+  const d = docker();
+  try {
+    await d.getImage(image).inspect();
+    return;
+  } catch (err) {
+    if (!isNotFound(err)) throw new Error(`could not inspect image ${image}: ${message(err)}`);
+  }
