+  // 124 is `timeout`'s own exit code; 137 is the SIGKILL from --kill-after.
+  const timedOut = backstopFired || exitCode === 124 || exitCode === 137;
+
+  return {
+    exitCode,
+    stdout: stdout.text(),
+    stderr: stderr.text(),
+    timedOut,
+    durationMs: Date.now() - started,
+  };
+}
