/** The CI command that best represents an action: the one CI runs most often. */
function representative(list: CiCommand[]): CiCommand {
  const counts = new Map<string, { command: CiCommand; count: number }>();
  for (const entry of list) {
    const key = normalizeCommand(entry.command);
    const seen = counts.get(key);
    if (seen) seen.count++;
    else counts.set(key, { command: entry, count: 1 });
  }
  let best = list[0]!;
  let bestCount = 0;
  for (const entry of counts.values()) {
    if (entry.count > bestCount) { best = entry.command; bestCount = entry.count; }
  }
  return best;
}
